arguments.file_text:
@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication

<div class="step-indicator d-flex align-items-center mb-4">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepNumber = i + 1;
        var isCompleted = CompletedSteps.Contains(stepNumber);
        var isCurrent = stepNumber == CurrentStep;
        var isClickable = isCompleted && !isCurrent;

        <div class="step text-center @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @((!isCurrent && !isCompleted) ? "future" : "")"
             role="@(isClickable ? "button" : "status")"
             @onclick="() => HandleStepClick(stepNumber)"
             style="cursor: @(isClickable ? "pointer" : "default"); flex: 0 0 auto;">
            <div class="step-circle rounded-circle d-flex align-items-center justify-content-center mx-auto mb-1"
                 style="width: 36px; height: 36px; font-weight: bold;
                        background-color: @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#dee2e6");
                        color: @(isCurrent || isCompleted ? "white" : "#6c757d");">
                @if (isCompleted && !isCurrent)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@stepNumber</span>
                }
            </div>
            <small class="d-block" style="white-space: nowrap; color: @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#adb5bd");">
                @StepNames[i]
            </small>
        </div>

        @if (i < StepNames.Count - 1)
        {
            <div class="flex-grow-1 mx-2" style="height: 2px; background-color: @(isCompleted ? "#198754" : "#dee2e6"); margin-bottom: 18px;"></div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = Array.Empty<string>();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step) && step != CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication
@using sv_d14198a9663740c1b668196523906da8.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="mb-0">Reference @Index</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="HandleRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name *</label>
                <InputText class="form-control" @bind-Value="Reference.Name" />
                <ValidationMessage For="() => Reference.Name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship *</label>
                <InputText class="form-control" @bind-Value="Reference.Relationship" />
                <ValidationMessage For="() => Reference.Relationship" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email *</label>
                <InputText class="form-control" @bind-Value="Reference.Email" />
                <ValidationMessage For="() => Reference.Email" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone *</label>
                <InputText class="form-control" @bind-Value="Reference.Phone" />
                <ValidationMessage For="() => Reference.Phone" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; } = 1;
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task HandleRemove() => await OnRemove.InvokeAsync();
}

@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication
@using sv_d14198a9663740c1b668196523906da8.Models
@using sv_d14198a9663740c1b668196523906da8.Services

@inject IApplicationService ApplicationService

<EditForm Model="Model" OnValidSubmit="HandleValidSubmit" OnInvalidSubmit="HandleInvalidSubmit" FormName="personal-info-step">
    <DataAnnotationsValidator />

    <h4 class="mb-3">Personal Information</h4>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name *</label>
            <InputText class="form-control" @bind-Value="Model.FullName" />
            <ValidationMessage For="() => Model.FullName" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <InputText class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (!string.IsNullOrEmpty(emailError))
            {
                <div class="text-danger mt-1">@emailError</div>
            }
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone *</label>
            <InputText class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Address *</label>
            <InputText class="form-control" @bind-Value="Model.Address" />
            <ValidationMessage For="() => Model.Address" />
        </div>
    </div>

    <div class="d-flex justify-content-end mt-4">
        <button type="submit" class="btn btn-primary" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Validating…</span>
            }
            else
            {
                <span>Next →</span>
            }
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private string? emailError;
    private bool isValidating;

    private void HandleInvalidSubmit()
    {
        emailError = null;
    }

    private async Task HandleValidSubmit()
    {
        emailError = null;
        isValidating = true;

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                emailError = "This email address could not be validated. Please check and try again.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}

@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication
@using sv_d14198a9663740c1b668196523906da8.Models
@using System.ComponentModel.DataAnnotations

<EditForm Model="this" OnSubmit="HandleSubmit" FormName="work-history-step">
    <h4 class="mb-3">Work History</h4>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="Entries[index]"
                         Index="index + 1"
                         ShowRemove="Entries.Count > 1"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (validationErrors.Count > 0)
    {
        <div class="alert alert-danger">
            <ul class="mb-0">
                @foreach (var error in validationErrors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    <div class="d-flex justify-content-between mt-3">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
        <button type="submit" class="btn btn-primary">Next →</button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private List<string> validationErrors = new();

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleSubmit()
    {
        validationErrors.Clear();

        for (int i = 0; i < Entries.Count; i++)
        {
            var entry = Entries[i];
            var context = new ValidationContext(entry);
            var results = new List<ValidationResult>();

            if (!Validator.TryValidateObject(entry, context, results, validateAllProperties: true))
            {
                foreach (var result in results)
                {
                    validationErrors.Add($"Position {i + 1}: {result.ErrorMessage}");
                }
            }
        }

        if (validationErrors.Count == 0)
        {
            await OnNext.InvokeAsync();
        }
    }
}

