@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <label class="form-label">Write your cover letter below</label>
    <textarea class="form-control" rows="12"
              maxlength="@MaxLength"
              @bind="coverLetterValue"
              @bind:event="oninput">
    </textarea>
    <div class="form-text text-end">
        @CoverLetter.Length / @MaxLength characters
    </div>
</div>

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between mt-4">
    <button type="button" class="btn btn-outline-secondary" @onclick="HandleBack">← Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? validationError;

    private string coverLetterValue
    {
        get => CoverLetter;
        set
        {
            CoverLetter = value;
            CoverLetterChanged.InvokeAsync(value);
        }
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();

    private async Task HandleNext()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            validationError = "Please write a cover letter before continuing.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication
@using sv_d14198a9663740c1b668196523906da8.Models
@using sv_d14198a9663740c1b668196523906da8.Services

@inject IApplicationService ApplicationService

<h4 class="mb-3">Review & Submit</h4>

@if (isSubmitted)
{
    <div class="alert alert-success text-center py-4">
        <h5 class="mb-2">🎉 Application Submitted Successfully!</h5>
        <p class="mb-0">Your application ID is: <strong>@applicationId</strong></p>
    </div>
}
else
{
    @* Personal Info *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @PersonalInfo.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @PersonalInfo.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @PersonalInfo.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @PersonalInfo.Address</div>
            </div>
        </div>
    </div>

    @* Work History *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom last-child-no-border">
                    <div><strong>@entry.Title</strong> at @entry.Company</div>
                    <div class="text-muted">
                        @entry.StartDate?.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <div class="mt-1">@entry.Description</div>
                    }
                </div>
            }
        </div>
    </div>

    @* References *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var reference in References)
            {
                <div class="mb-2">
                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
                    <span class="text-muted">@reference.Email · @reference.Phone</span>
                </div>
            }
        </div>
    </div>

    @* Cover Letter *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(4)">Edit</button>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@CoverLetter</p>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(submitError))
    {
        <div class="alert alert-danger">@submitError</div>
    }

    <div class="d-flex justify-content-between mt-4">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
            @if (isSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Submitting…</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }

    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var personal = new PersonalInfo(
                PersonalInfo.FullName, PersonalInfo.Email,
                PersonalInfo.Phone, PersonalInfo.Address);

            var workEntries = WorkEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate!.Value,
                e.IsCurrent ? null : e.EndDate, e.Description)).ToList();

            var references = References.Select(r => new Reference(
                r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(
                personal, new WorkHistory(workEntries), references, CoverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"An error occurred while submitting: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication

<div class="step-indicator d-flex align-items-center mb-4">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepNumber = i + 1;
        var isCompleted = CompletedSteps.Contains(stepNumber);
        var isCurrent = stepNumber == CurrentStep;
        var isClickable = isCompleted && !isCurrent;

        <div class="step text-center @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @((!isCurrent && !isCompleted) ? "future" : "")"
             role="@(isClickable ? "button" : "status")"
             @onclick="() => HandleStepClick(stepNumber)"
             style="cursor: @(isClickable ? "pointer" : "default"); flex: 0 0 auto;">
            <div class="step-circle rounded-circle d-flex align-items-center justify-content-center mx-auto mb-1"
                 style="width: 36px; height: 36px; font-weight: bold;
                        background-color: @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#dee2e6");
                        color: @(isCurrent || isCompleted ? "white" : "#6c757d");">
                @if (isCompleted && !isCurrent)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@stepNumber</span>
                }
            </div>
            <small class="d-block" style="white-space: nowrap; color: @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#adb5bd");">
                @StepNames[i]
            </small>
        </div>

        @if (i < StepNames.Count - 1)
        {
            <div class="flex-grow-1 mx-2" style="height: 2px; background-color: @(isCompleted ? "#198754" : "#dee2e6"); margin-bottom: 18px;"></div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = Array.Empty<string>();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step) && step != CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

