@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }

    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var personal = new PersonalInfo(
                PersonalInfo.FullName, PersonalInfo.Email,
                PersonalInfo.Phone, PersonalInfo.Address);

            var workEntries = WorkEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate!.Value,
                e.IsCurrent ? null : e.EndDate, e.Description)).ToList();

            var references = References.Select(r => new Reference(
                r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(
                personal, new WorkHistory(workEntries), references, CoverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"An error occurred while submitting: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

