@namespace sv_d14198a9663740c1b668196523906da8.Components.JobApplication
@using sv_d14198a9663740c1b668196523906da8.Models
@using System.ComponentModel.DataAnnotations

<EditForm Model="this" OnSubmit="HandleSubmit" FormName="references-step">
    <h4 class="mb-3">References</h4>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceEditor Reference="References[index]"
                         Index="index + 1"
                         ShowRemove="References.Count > 2"
                         OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (validationErrors.Count > 0)
    {
        <div class="alert alert-danger">
            <ul class="mb-0">
                @foreach (var error in validationErrors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    <div class="d-flex justify-content-between mt-3">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
        <button type="submit" class="btn btn-primary">Next →</button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private List<string> validationErrors = new();

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleSubmit()
    {
        validationErrors.Clear();

        for (int i = 0; i < References.Count; i++)
        {
            var reference = References[i];
            var context = new ValidationContext(reference);
            var results = new List<ValidationResult>();

            if (!Validator.TryValidateObject(reference, context, results, validateAllProperties: true))
            {
                foreach (var result in results)
                {
                    validationErrors.Add($"Reference {i + 1}: {result.ErrorMessage}");
                }
            }
        }

        if (validationErrors.Count == 0)
        {
            await OnNext.InvokeAsync();
        }
    }
}

